package io.stronghold.protocol;
import android.app.*;
import android.os.*;
import android.content.*;
import android.content.pm.ActivityInfo;
import android.content.res.Configuration;
import android.graphics.Color;
import android.net.Uri;
import android.webkit.*;
import android.widget.*;
import android.view.*;
import java.net.URI;
import java.util.concurrent.*;
import org.json.*;
public final class MainActivity extends Activity {
  private WebView web;private EditText address;private ClientConnectionView entry;private Button connect,serverButton;private boolean playing;private volatile URI server;private volatile ResourceStore resources;private boolean busy;private final ExecutorService worker=Executors.newSingleThreadExecutor();
  private android.content.SharedPreferences preferences;
  private LinearLayout contentRoot;private View orientationHint;private boolean portraitBlocked;
  @Override public void onCreate(Bundle saved){super.onCreate(saved);setRequestedOrientation(ActivityInfo.SCREEN_ORIENTATION_SENSOR_LANDSCAPE);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);if(Build.VERSION.SDK_INT>=30)getWindow().setDecorFitsSystemWindows(false);preferences=getSharedPreferences("connection",MODE_PRIVATE);
    LinearLayout root=new LinearLayout(this);contentRoot=root;root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(Color.rgb(12,15,14));root.setGravity(Gravity.CENTER);entry=new ClientConnectionView(this);address=entry.address;connect=entry.connect;address.setText(preferences.getString("server",""));root.addView(entry,new LinearLayout.LayoutParams(-1,-2));serverButton=new Button(this);serverButton.setText("更换服务器");serverButton.setTextSize(12);serverButton.setTextColor(ClientConnectionView.MINT);serverButton.setBackgroundColor(Color.rgb(20,24,22));serverButton.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);serverButton.setPadding(16,0,16,0);serverButton.setVisibility(View.GONE);root.addView(serverButton,new LinearLayout.LayoutParams(-1,Math.round(44*getResources().getDisplayMetrics().density)));serverButton.setOnClickListener(v->showConnection());web=new ClientWebView(this);web.setFocusable(true);web.setFocusableInTouchMode(true);web.setBackgroundColor(Color.rgb(12,15,14));web.setVisibility(View.GONE);root.addView(web,new LinearLayout.LayoutParams(-1,0,1));address.setOnEditorActionListener((v,action,event)->{if(action==android.view.inputmethod.EditorInfo.IME_ACTION_GO){connect();return true;}return false;});
    FrameLayout host=new FrameLayout(this);host.addView(root,new FrameLayout.LayoutParams(-1,-1));orientationHint=createOrientationHint();host.addView(orientationHint,new FrameLayout.LayoutParams(-1,-1));setContentView(host);host.addOnLayoutChangeListener((v,l,t,r,b,ol,ot,or,ob)->updateOrientationHint());updateOrientationHint();
    WebSettings settings=web.getSettings();settings.setJavaScriptEnabled(true);settings.setDomStorageEnabled(true);settings.setAllowFileAccess(false);settings.setAllowContentAccess(false);settings.setMediaPlaybackRequiresUserGesture(false);settings.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);CookieManager.getInstance().setAcceptCookie(true);CookieManager.getInstance().setAcceptThirdPartyCookies(web,false);web.addJavascriptInterface(new Bridge(),"SPAndroid");
    root.setOnApplyWindowInsetsListener((view,insets)->{if(Build.VERSION.SDK_INT>=30){android.graphics.Insets safe=insets.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout()|WindowInsets.Type.ime());view.setPadding(safe.left,safe.top,safe.right,safe.bottom);serverButton.setVisibility(!playing&&web.getVisibility()==View.VISIBLE&&!insets.isVisible(WindowInsets.Type.ime())?View.VISIBLE:View.GONE);}else view.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets;});root.requestApplyInsets();
    web.setWebChromeClient(new WebChromeClient());web.setWebViewClient(new WebViewClient(){
      @Override public void onPageFinished(WebView view,String url){try{URI target=new URI(url);if(!busy&&server!=null&&same(server,target)&&target.getPath().equals("/product/login.html"))entry.idle("服务器已连接，请登录账号");}catch(Exception ignored){}}
      @Override public void onReceivedError(WebView view,WebResourceRequest request,WebResourceError error){if(request.isForMainFrame()){showConnection();entry.error("无法连接服务器，请检查地址后重试");}}
      @Override public void onPageStarted(WebView view,String url,android.graphics.Bitmap icon){try{if(new URI(url).getPath().equals("/product/login.html"))gameLayout(false);}catch(Exception ignored){}}
      @Override public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest request){URI selected=server;try{URI target=new URI(request.getUrl().toString());return selected==null||!same(selected,target)||account(target.getPath())||!page(target.getPath());}catch(Exception error){return true;}}
      @Override public WebResourceResponse shouldInterceptRequest(WebView view,WebResourceRequest request){try{String requested=request.getUrl().toString();if(requested.startsWith("data:")||requested.startsWith("blob:"))return null;URI selected=server,target=new URI(requested);if(selected==null||!same(selected,target)||account(target.getPath()))return ResourceStore.error(403);if(ResourceStore.fixed(target.getPath()))return resources==null?ResourceStore.error(503):resources.response(target.getRawPath(),request.getMethod(),request.getRequestHeaders().get("Range"));return null;}catch(Exception error){return ResourceStore.error(503);}}
      @Override public void onReceivedSslError(WebView view,SslErrorHandler handler,android.net.http.SslError error){handler.cancel();progress("服务器证书验证失败");}
    });connect.setOnClickListener(v->connect());WebView.setWebContentsDebuggingEnabled((getApplicationInfo().flags&android.content.pm.ApplicationInfo.FLAG_DEBUGGABLE)!=0);
    worker.execute(()->{try{resources=new ResourceStore(this,this::progress);runOnUiThread(()->{settings.setUserAgentString(settings.getUserAgentString()+" "+resources.agent());connect.setEnabled(true);progress("本地资源已校验",1,1);if(address.length()>0)connect();});}catch(Exception error){progress(error.getMessage());}});
  }
  private View createOrientationHint(){
    LinearLayout hint=new LinearLayout(this);hint.setOrientation(LinearLayout.VERTICAL);hint.setGravity(Gravity.CENTER);hint.setBackgroundColor(Color.rgb(12,15,14));
    int padding=Math.round(24*getResources().getDisplayMetrics().density);hint.setPadding(padding,padding,padding,padding);hint.setClickable(true);hint.setFocusableInTouchMode(true);
    TextView title=new TextView(this);title.setText(R.string.landscape_required);title.setTextSize(24);title.setTextColor(Color.rgb(23,249,183));title.setGravity(Gravity.CENTER);hint.addView(title);
    TextView help=new TextView(this);help.setText(R.string.landscape_help);help.setTextSize(16);help.setTextColor(Color.LTGRAY);help.setGravity(Gravity.CENTER);help.setPadding(0,padding,0,0);hint.addView(help);
    hint.setVisibility(View.GONE);return hint;
  }
  private void updateOrientationHint(){
    if(orientationHint==null)return;
    boolean blocked=getResources().getConfiguration().orientation==Configuration.ORIENTATION_PORTRAIT;
    if(blocked==portraitBlocked)return;portraitBlocked=blocked;
    // Keep the WebView and its session alive while preventing interaction in forced portrait windows.
    contentRoot.setVisibility(blocked?View.INVISIBLE:View.VISIBLE);orientationHint.setVisibility(blocked?View.VISIBLE:View.GONE);
    if(blocked){orientationHint.requestFocus();android.view.inputmethod.InputMethodManager ime=(android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE);if(ime!=null)ime.hideSoftInputFromWindow(orientationHint.getWindowToken(),0);}else if(web.getVisibility()==View.VISIBLE){web.requestFocus(View.FOCUS_DOWN);}
  }
  @Override protected void onResume(){super.onResume();if(getRequestedOrientation()!=ActivityInfo.SCREEN_ORIENTATION_SENSOR_LANDSCAPE)setRequestedOrientation(ActivityInfo.SCREEN_ORIENTATION_SENSOR_LANDSCAPE);updateOrientationHint();}
  @Override public void onConfigurationChanged(Configuration configuration){super.onConfigurationChanged(configuration);updateOrientationHint();}
  private static boolean same(URI a,URI b){return a.getScheme().equals(b.getScheme())&&a.getHost().equalsIgnoreCase(b.getHost())&&port(a)==port(b);}
  private static int port(URI uri){return uri.getPort()<0?(uri.getScheme().equals("https")?443:80):uri.getPort();}
  private static boolean page(String path){return path.equals("/")||path.equals("/index.html")||path.equals("/product/login.html");}
  private static boolean account(String p){String path=p.toLowerCase(java.util.Locale.ROOT);return path.startsWith("/admin")||path.startsWith("/account")||path.startsWith("/auth/admin/")||path.equals("/auth/password");}
  private void connect(){if(busy||resources==null)return;try{URI selected=new URI(address.getText().toString().trim());if(!("http".equals(selected.getScheme())||"https".equals(selected.getScheme()))||selected.getHost()==null||selected.getUserInfo()!=null||selected.getQuery()!=null||selected.getFragment()!=null||!"/".equals(selected.getPath())&&!"".equals(selected.getPath()))throw new Exception("请填写服务器根地址，例如 http://公网IP:3000");selected=new URI(selected.getScheme(),null,selected.getHost(),selected.getPort(),"/",null,null);if(server!=null&&!same(server,selected)){URI target=selected;new AlertDialog.Builder(this).setMessage("切换服务器将断开当前对局。继续？").setPositiveButton("继续",(d,w)->{web.stopLoading();CookieManager.getInstance().removeAllCookies(value->open(target));}).setNegativeButton("取消",null).show();}else open(selected);}catch(Exception error){progress(error.getMessage());}}
  private void open(URI selected){server=selected;preferences.edit().putString("server",selected.toString()).apply();entry.compact();entry.setVisibility(View.GONE);serverButton.setVisibility(View.VISIBLE);contentRoot.setGravity(Gravity.TOP);web.setVisibility(View.VISIBLE);progress("正在连接服务器…",-1,0);android.view.inputmethod.InputMethodManager ime=(android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE);if(ime!=null)ime.hideSoftInputFromWindow(address.getWindowToken(),0);address.clearFocus();entry.clearFocus();web.requestFocus(View.FOCUS_DOWN);web.loadUrl(selected.resolve("/product/login.html").toString());}
  private void gameLayout(boolean playing){this.playing=playing;entry.setVisibility(View.GONE);serverButton.setVisibility(playing?View.GONE:View.VISIBLE);contentRoot.requestApplyInsets();if(Build.VERSION.SDK_INT>=30){android.view.WindowInsetsController controller=getWindow().getDecorView().getWindowInsetsController();if(controller!=null){if(playing){controller.setSystemBarsBehavior(android.view.WindowInsetsController.BEHAVIOR_SHOW_TRANSIENT_BARS_BY_SWIPE);controller.hide(WindowInsets.Type.systemBars());}else controller.show(WindowInsets.Type.systemBars());}}else getWindow().getDecorView().setSystemUiVisibility(playing?View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY|View.SYSTEM_UI_FLAG_FULLSCREEN|View.SYSTEM_UI_FLAG_HIDE_NAVIGATION:View.SYSTEM_UI_FLAG_VISIBLE);}
  private void showConnection(){if(busy)return;playing=false;web.clearFocus();web.setVisibility(View.GONE);serverButton.setVisibility(View.GONE);entry.setVisibility(View.VISIBLE);if(resources!=null)entry.compact();contentRoot.setGravity(Gravity.CENTER);address.requestFocus();}
  private void progress(String text){runOnUiThread(()->{showConnection();entry.error(text);});}
  private void progress(String text,long completed,long total){runOnUiThread(()->{entry.update(text,completed,total);try{URI source=new URI(web.getUrl()==null?"":web.getUrl());if(server!=null&&same(server,source)&&source.getPath().equals("/product/login.html")){JSONObject message=new JSONObject().put("type","resource-progress").put("label",text).put("completed",completed).put("total",total);web.evaluateJavascript("window.dispatchEvent(new MessageEvent('sp-native-response',{data:"+message.toString()+"}))",null);}}catch(Exception ignored){}});}
  final class Bridge {
    @JavascriptInterface public void request(String raw){runOnUiThread(()->{JSONObject request;int id;try{request=new JSONObject(raw);id=request.getInt("id");URI source=new URI(web.getUrl());if(server==null||!same(server,source)||!page(source.getPath()))throw new Exception("客户端来源无效");String method=request.getString("method");if(method.equals("status")){reply(id,resources.status(),null);return;}if(method.equals("enter")){if(source.getPath().equals("/product/login.html"))throw new Exception("请从游戏页面进入");gameLayout(true);reply(id,new JSONObject().put("action","ready"),null);return;}if(!method.equals("prepare")||!source.getPath().equals("/product/login.html")||busy)throw new Exception("请在登录页面更新资源");busy=true;connect.setEnabled(false);serverButton.setEnabled(false);String cookie=CookieManager.getInstance().getCookie(server.toString());URI selected=server;worker.execute(()->{try{JSONObject result=resources.prepare(selected,cookie,MainActivity.this::progress);runOnUiThread(()->{String ua=web.getSettings().getUserAgentString();web.getSettings().setUserAgentString(ua.substring(0,ua.indexOf("StrongholdProtocolApp/"))+resources.agent());reply(id,result,null);});}catch(Exception error){runOnUiThread(()->{entry.error(error.getMessage());reply(id,null,error.getMessage());});}finally{runOnUiThread(()->{busy=false;connect.setEnabled(true);serverButton.setEnabled(true);});}});}catch(Exception error){int failed;try{failed=new JSONObject(raw).optInt("id");}catch(Exception ignored){failed=0;}reply(failed,null,error.getMessage());}});}
  }
  private void reply(int id,JSONObject result,String error){try{JSONObject message=new JSONObject().put("id",id);if(error!=null)message.put("error",error);else message.put("result",result);web.evaluateJavascript("window.dispatchEvent(new MessageEvent('sp-native-response',{data:"+message.toString()+"}))",null);}catch(Exception ignored){}}
  @Override public void onBackPressed(){new AlertDialog.Builder(this).setMessage("退出客户端会断开连接。继续？").setPositiveButton("退出",(d,w)->finish()).setNegativeButton("取消",null).show();}
  @Override protected void onDestroy(){web.destroy();worker.shutdownNow();if(resources!=null)try{resources.close();}catch(Exception ignored){}super.onDestroy();}
}
